import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

max_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor max_reduce(torch::Tensor x, int64_t dim);
"""

max_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>
#include <math.h>
#include <vector>
#include <algorithm>

using namespace cute;

template <int Threads, int Segments>
__global__ void max_reduce_dim_partial_kernel(const float* __restrict__ X,
                                              float* __restrict__ P,
                                              int outer,
                                              int R,
                                              int inner)
{
  const int o = blockIdx.z + blockIdx.y * gridDim.z;
  if (o >= outer) return;
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  if (i >= inner) return;
  const int seg = threadIdx.y;
  if (seg >= Segments) return;
  const int seg_len = (R + Segments - 1) / Segments;
  const int r0 = seg * seg_len;
  const int r1 = min(R, r0 + seg_len);
  const float* x_base = X + (int64_t)o * (int64_t)R * (int64_t)inner;
  float* p_base = P + ((int64_t)o * (int64_t)Segments + seg) * (int64_t)inner;
  Tensor mX = make_tensor(make_gmem_ptr(x_base),
                          make_shape(R, inner),
                          make_stride(inner, Int<1>{}));
  float acc = -INFINITY;
  constexpr int kRUnroll = 8;
  int r = r0;
  for (; r + kRUnroll <= r1; r += kRUnroll) {
    float v[kRUnroll];
    #pragma unroll
    for (int rr = 0; rr < kRUnroll; ++rr) {
      v[rr] = mX(r + rr, i);
    }
    #pragma unroll
    for (int rr = 0; rr < kRUnroll; ++rr) {
      acc = fmaxf(acc, v[rr]);
    }
  }
  for (; r < r1; ++r) {
    acc = fmaxf(acc, mX(r, i));
  }
  p_base[i] = acc;
}
template <int Threads>
__global__ void max_reduce_dim_final_kernel(const float* __restrict__ P,
                                            float* __restrict__ Y,
                                            int outer,
                                            int inner,
                                            int segments)
{
  const int o = blockIdx.z + blockIdx.y * gridDim.z;
  if (o >= outer) return;
  const int i = blockIdx.x * Threads + threadIdx.x;
  if (i >= inner) return;
  const float* p_base = P + (int64_t)o * (int64_t)segments * (int64_t)inner;
  float* y_base = Y + (int64_t)o * (int64_t)inner;
  Tensor mP = make_tensor(make_gmem_ptr(p_base),
                          make_shape(segments, inner),
                          make_stride(inner, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(y_base),
                          make_shape(inner),
                          make_stride(Int<1>{}));
  float acc = -INFINITY;
  for (int s = 0; s < segments; ++s) {
    acc = fmaxf(acc, mP(s, i));
  }
  mY(i) = acc;
}

torch::Tensor max_reduce(torch::Tensor x, int64_t dim)
{
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() >= 1, "x must have at least 1 dimension");

  auto x_c = x.contiguous();
  int64_t nd = x_c.dim();
  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
  int64_t R = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < nd; ++d) inner *= x_c.size(d);

  std::vector<int64_t> out_sizes;
  out_sizes.reserve(nd - 1);
  for (int64_t d = 0; d < nd; ++d) {
    if (d != dim) out_sizes.push_back(x_c.size(d));
  }

  auto y = torch::empty(out_sizes, x_c.options());

  constexpr int Threads = 256;
  constexpr int Segments = 4;
  const int64_t partial_elems = outer * (int64_t)Segments * inner;
  auto partial = torch::empty({partial_elems}, x_c.options());
  const int64_t max_z = 65535;
  const int64_t outer_chunks = (outer + max_z - 1) / max_z;
  const int64_t outer_per_chunk = std::min<int64_t>(outer, max_z);
  const int partial_tx = 128;
  const int64_t inner_blocks_partial = (inner + partial_tx - 1) / partial_tx;
  const int64_t inner_blocks_final = (inner + Threads - 1) / Threads;
  dim3 partial_block(partial_tx, Segments);
  dim3 partial_grid((unsigned)inner_blocks_partial, (unsigned)outer_chunks, (unsigned)outer_per_chunk);
  dim3 final_block(Threads);
  dim3 final_grid((unsigned)inner_blocks_final, (unsigned)outer_chunks, (unsigned)outer_per_chunk);
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  max_reduce_dim_partial_kernel<Threads, Segments><<<partial_grid, partial_block, 0, stream>>>(
      x_c.data_ptr<float>(),
      partial.data_ptr<float>(),
      (int)outer,
      (int)R,
      (int)inner);
  max_reduce_dim_final_kernel<Threads><<<final_grid, final_block, 0, stream>>>(
      partial.data_ptr<float>(),
      y.data_ptr<float>(),
      (int)outer,
      (int)inner,
      Segments);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

max_ext = load_inline(
    name="cute_max_reduce_ext",
    cpp_sources=max_cpp_decl,
    cuda_sources=max_cuda_src,
    functions=["max_reduce"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Max reduction over a specific dimension using one custom CUTE/CUDA kernel.
    Optimized for the provided case: x is [128, 4096, 4095], dim=1.
    """
    def __init__(self, dim: int):
        super().__init__()
        self.dim = int(dim)
        self._ext = max_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.max_reduce(x, self.dim)

