                          make_shape(R, inner),
                          make_stride(inner, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(y_base),
                          make_shape(inner),
                          make_stride(Int<1>{}));
  int idx[kInnerUnroll];
  bool valid[kInnerUnroll];
  float acc[kInnerUnroll];
  #pragma unroll
  for (int k = 0; k < kInnerUnroll; ++k) {
